# Detect repeated 8-gram positions in the loop text; rank MLP units by loop-vs-normal activation
import numpy as np, json
d5='/work/fwd_5'
meta5=json.load(open(d5+'/meta.json'))
ids5=meta5['token_ids']; lens5=meta5['lengths']
print(lens5)
def loop_positions(ids, L, n=8):
    seen={}
    loop=np.zeros(L, dtype=bool)
    for i in range(L):
        if i>=n:
            g=tuple(ids[i-n:i])
            if g in seen:
                loop[i-n:i]=True  # positions inside repeated block (content tokens)
            seen[g]=i
    return loop
for ti in range(2):
    L=lens5[ti]; ids=ids5[ti]
    lp = loop_positions(ids, L)
    print(f'text{ti} L={L} looppos={lp.sum()} frac={lp.mean():.2f}')

